(7698978, 1263337, 30049, '<td valign="top">Very harsh processing at play here.  Does do a nice job of B&amp;W impact that way.  Weird smudge next to the lighthouse.  ???  I think you may also be due for a sensor cleaning.  :-}</td>', 'Very harsh processing at play here.  Does do a nice job of B&W impact that way.  Weird smudge next to the lighthouse.  ???  I think you may also be due for a sensor cleaning.  :-}', '2021-08-14 22:27:15.000000', NULL, 1),
(7698979, 1263407, 30049, '<td valign="top">Now this is an interesting interpretation.  I like it.  The distant ships make this work absolutely.  Well done!</td>', 'Now this is an interesting interpretation.  I like it.  The distant ships make this work absolutely.  Well done!', '2021-08-14 22:29:31.000000', NULL, 1),
(7698980, 1263129, 30049, '<td valign="top">Unusual ratio in the crop.  Not sure if I like it or not.  The extra height feels like it takes away from the wide open space here.  Just one persons opinion of course.  Good luck.</td>', 'Unusual ratio in the crop.  Not sure if I like it or not.  The extra height feels like it takes away from the wide open space here.  Just one persons opinion of course.  Good luck.', '2021-08-14 22:32:34.000000', NULL, 1),
